compile.workshop:
variables {
    global:
        0: g
        1: h
        2: A
}

rule ("true if") {
    event {
        Ongoing - Global;
    }
    actions {
        Set Global Variable(g, 1);
    }
}

rule ("true if else") {
    event {
        Ongoing - Global;
    }
    actions {
        Set Global Variable(g, 1);
    }
}

rule ("false if else") {
    event {
        Ongoing - Global;
    }
    actions {
        Set Global Variable(g, 2);
    }
}

rule ("false elif") {
    event {
        Ongoing - Global;
    }
    actions {
        If(Compare(Global.A, ==, 1));
            Set Global Variable(g, 1);
        Else;
            Set Global Variable(g, 3);
    }
}

rule ("true elif") {
    event {
        Ongoing - Global;
    }
    actions {
        If(Compare(Global.A, ==, 1));
            Set Global Variable(g, 1);
        Else;
            Set Global Variable(g, 2);
    }
}

rule ("false if true elif") {
    event {
        Ongoing - Global;
    }
    actions {
        Set Global Variable(g, 2);
    }
}

rule ("false if live elif") {
    event {
        Ongoing - Global;
    }
    actions {
        If(Compare(Global.A, ==, 2));
            Set Global Variable(g, 2);
        Else;
            Set Global Variable(g, 3);
    }
}

rule ("nested") {
    event {
        Ongoing - Global;
    }
    actions {
        If(Compare(Global.A, ==, 1));
            Set Global Variable(g, 1);
            Set Global Variable(h, 3);
    }
}

rule ("in while") {
    event {
        Ongoing - Global;
    }
    actions {
        While(Compare(Global.A, ==, 1));
            Set Global Variable(g, 1);
            Wait(1, Ignore Condition);
        End;
    }
}

rule ("live condition") {
    event {
        Ongoing - Global;
    }
    actions {
        If(Compare(Global.A, ==, 1));
            Set Global Variable(g, 1);
    }
}

